import { useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Download, ChevronLeft, ChevronRight, Play, X, Circle } from "lucide-react";
import pdf from "../assets/abdul.pdf";

const slides = [
  {
    key: "marsad",
    roleLine: "Front-End Developer at Numerique360",
    title: "ERP & WooCommerce (Marsad)",
    desc: "Built ERP dashboards and WooCommerce-integrated modules, including custom WordPress plugin work and a headless Menu REST API endpoint. Delivered filters, pagination, analytics, and performance improvements.",
    videoSrc: "/videos/marsad.mov"
  },
  {
    key: "swapxe",
    roleLine: "Front-End Developer at Numerique360",
    title: "Crypto Dashboard (SwapXe)",
    desc: "Built a secure dashboard with JWT authentication and real-time API data display for wallet and transaction views. Focused on responsive UI, reliability, and clean components.",
    videoSrc: "/videos/swapxe.mov"
  },
  {
    key: "aviation",
    roleLine: "Front-End Developer at Numerique360",
    title: "Aviation ERP (Bug Fixing)",
    desc: "Worked on maintenance and bug fixes in an aviation ERP system, resolving UI/functional issues and improving stability and error handling in production flows.",
    videoSrc: "/videos/aviation_erp.mov"
  },
  {
    key: "blockchain",
    roleLine: "Front-End Developer at Numerique360",
    title: "Crypto Quote / Exchange APIs",
    desc: "Integrated external pricing/quote APIs to show real-time market data and refresh logic with error handling. Focused on accurate display and UI performance.",
    videoSrc: "/videos/blockchain.mov"
  },
  {
    key: "jobbot",
    roleLine: "Front-End Developer at Numerique360",
    title: "Automation Platform (Job Bot)",
    desc: "Built a full-stack automation platform with a live monitoring dashboard, showing run status and step-level updates. Focused on structured UI and real-time feedback.",
    videoSrc: "/videos/jobbot.mov"
  }
];

export default function WorkExperience() {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [direction, setDirection] = useState(0);
  const [selectedVideo, setSelectedVideo] = useState(null);
  const [isPaused, setIsPaused] = useState(false);

  // Auto-advance
  useEffect(() => {
    if (isPaused || selectedVideo) return;
    const timer = setInterval(() => {
      nextSlide();
    }, 7000); // 7s auto-advance
    return () => clearInterval(timer);
  }, [currentSlide, isPaused, selectedVideo]);

  // Lock scroll when modal is open
  useEffect(() => {
    if (selectedVideo) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }
  }, [selectedVideo]);

  // Handle ESC for modal
  useEffect(() => {
    const handleEsc = (e) => {
      if (e.key === "Escape") setSelectedVideo(null);
    };
    window.addEventListener("keydown", handleEsc);
    return () => window.removeEventListener("keydown", handleEsc);
  }, []);

  const nextSlide = useCallback(() => {
    setDirection(1);
    setCurrentSlide((prev) => (prev + 1) % slides.length);
  }, []);

  const prevSlide = useCallback(() => {
    setDirection(-1);
    setCurrentSlide((prev) => (prev - 1 + slides.length) % slides.length);
  }, []);

  const goToSlide = (index) => {
    setDirection(index > currentSlide ? 1 : -1);
    setCurrentSlide(index);
  };

  const slideVariants = {
    enter: (direction) => ({
      x: direction > 0 ? 1000 : -1000,
      opacity: 0
    }),
    center: {
      zIndex: 1,
      x: 0,
      opacity: 1
    },
    exit: (direction) => ({
      zIndex: 0,
      x: direction < 0 ? 1000 : -1000,
      opacity: 0
    })
  };

  const swipeConfidenceThreshold = 10000;
  const swipePower = (offset, velocity) => {
    return Math.abs(offset) * velocity;
  };

  const current = slides[currentSlide];

  return (
    <motion.section
      id="wxp"
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.6 }}
      className="max-w-4xl mx-auto px-4 py-12 bg-white dark:bg-gray-900 rounded-xl shadow-xl overflow-hidden"
    >
      <h2 className="text-3xl font-bold mb-8 text-center text-gray-900 dark:text-white pt-10">
        Work Experience
      </h2>

      <div
        className="relative min-h-[600px] flex flex-col justify-center"
        onMouseEnter={() => setIsPaused(true)}
        onMouseLeave={() => setIsPaused(false)}
      >
        {/* Navigation Buttons */}
        <button
          onClick={prevSlide}
          className="absolute left-0 top-1/2 -translate-y-1/2 -translate-x-2 md:-translate-x-12 z-20 
            p-2 rounded-full bg-gray-200 dark:bg-gray-800 text-gray-800 dark:text-white 
            hover:bg-gray-300 dark:hover:bg-gray-700 transition shadow-lg"
          aria-label="Previous Slide"
        >
          <ChevronLeft className="w-6 h-6" />
        </button>
        <button
          onClick={nextSlide}
          className="absolute right-0 top-1/2 -translate-y-1/2 translate-x-2 md:translate-x-12 z-20 
            p-2 rounded-full bg-gray-200 dark:bg-gray-800 text-gray-800 dark:text-white 
            hover:bg-gray-300 dark:hover:bg-gray-700 transition shadow-lg"
          aria-label="Next Slide"
        >
          <ChevronRight className="w-6 h-6" />
        </button>

        {/* Carousel Content */}
        <div className="relative w-full overflow-hidden h-full flex items-center">
          <AnimatePresence initial={false} custom={direction}>
            <motion.div
              key={currentSlide}
              custom={direction}
              variants={slideVariants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{
                x: { type: "spring", stiffness: 300, damping: 30 },
                opacity: { duration: 0.2 }
              }}
              drag="x"
              dragConstraints={{ left: 0, right: 0 }}
              dragElastic={1}
              onDragEnd={(e, { offset, velocity }) => {
                const swipe = swipePower(offset.x, velocity.x);
                if (swipe < -swipeConfidenceThreshold) {
                  nextSlide();
                } else if (swipe > swipeConfidenceThreshold) {
                  prevSlide();
                }
              }}
              className="absolute w-full flex flex-col items-center text-center px-4 md:px-12"
            >
              <h3 className="text-sm font-semibold text-blue-600 uppercase tracking-widest mb-2">
                {current.roleLine}
              </h3>
              <h4 className="text-2xl md:text-3xl font-bold text-gray-900 dark:text-white mb-4">
                {current.title}
              </h4>
              <p className="text-gray-700 dark:text-gray-300 mb-6 max-w-2xl leading-relaxed">
                {current.desc}
              </p>

              <a
                href={pdf}
                download
                className="inline-flex items-center gap-2 px-6 py-3 mb-8 bg-blue-600 text-white rounded-lg shadow 
                  hover:bg-blue-700 transition transform hover:scale-105"
              >
                <Download className="w-5 h-5" /> Download Resume
              </a>

              {/* Video Preview */}
              <div
                className="relative w-full max-w-lg rounded-xl overflow-hidden shadow-2xl cursor-pointer group"
                onClick={() => setSelectedVideo(current.videoSrc)}
              >
                <div className="absolute inset-0 bg-black/30 group-hover:bg-black/10 transition-colors z-10" />
                <div className="absolute inset-0 flex items-center justify-center z-20">
                  <div className="bg-white/90 dark:bg-black/80 p-4 rounded-full shadow-xl transform group-hover:scale-110 transition-transform">
                    <Play className="w-8 h-8 text-blue-600 fill-current ml-1" />
                  </div>
                </div>
                <video
                  src={current.videoSrc}
                  className="w-full h-auto object-cover aspect-video bg-gray-100 dark:bg-gray-800"
                  muted
                  loop
                  playsInline
                  autoPlay
                  preload="metadata"
                />
              </div>
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Height Spacer (invisible, keeps container height stable during transitions) */}
        <div className="invisible flex flex-col items-center px-4 md:px-12 pointer-events-none">
          <h3 className="text-sm font-semibold uppercase tracking-widest mb-2">Spacer</h3>
          <h4 className="text-2xl md:text-3xl font-bold mb-4">Spacer Title</h4>
          <p className="mb-6 max-w-2xl leading-relaxed">
            Placeholder text to maintain the height of the container so it doesn't collapse or jump
            when slides are changing absolutely. This should validly approximate the max content size.
          </p>
          <div className="px-6 py-3 mb-8">Button</div>
          <div className="w-full max-w-lg aspect-video"></div>
        </div>

        {/* Indicators */}
        <div className="flex justify-center gap-2 mt-8 absolute bottom-0 left-0 right-0 py-4">
          {slides.map((_, idx) => (
            <button
              key={idx}
              onClick={() => goToSlide(idx)}
              className={`transition-all duration-300 ${idx === currentSlide
                  ? "text-blue-600 scale-125"
                  : "text-gray-400 dark:text-gray-600 hover:text-gray-600 dark:hover:text-gray-400"
                }`}
              aria-label={`Go to slide ${idx + 1}`}
            >
              <Circle className={`w-3 h-3 ${idx === currentSlide ? "fill-current" : ""}`} />
            </button>
          ))}
        </div>
      </div>

      {/* Video Modal */}
      <AnimatePresence>
        {selectedVideo && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4"
            onClick={() => setSelectedVideo(null)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="relative w-full max-w-5xl bg-black rounded-2xl overflow-hidden shadow-2xl"
              onClick={(e) => e.stopPropagation()}
            >
              <button
                onClick={() => setSelectedVideo(null)}
                className="absolute top-4 right-4 p-2 bg-black/50 hover:bg-black/70 text-white rounded-full transition-colors z-10"
              >
                <X className="w-6 h-6" />
              </button>

              <video
                src={selectedVideo}
                controls
                autoPlay
                className="w-full h-auto max-h-[85vh] object-contain mx-auto"
              >
                Your browser does not support the video tag.
              </video>

              <div className="p-4 bg-gray-900 text-center">
                <p className="text-sm text-gray-400">
                  If the video doesn’t play in your browser, an MP4 version will be provided.
                </p>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.section>
  );
}
